// Merchant previews show the same footer customers get: the business
// address plus an Unsubscribe link (inert here; the real per-recipient link
// is added at send time).
async function previewFooterLine(admin: Parameters<typeof loadShopFooterAddress>[0], shop: string) {
  const [settings, shopAddress] = await Promise.all([
    db.shopSettings.findUnique({ where: { shop } }),
    loadShopFooterAddress(admin),
  ]);
  return resolveSenderFooter(settings, shopAddress).line;
}
