const CAMPAIGN_PAGE_SIZE = 12;

function resolveCampaignLanguage(value: string | undefined): EmailLanguage {
  return EMAIL_LANGUAGES.some(({ code }) => code === value) ? (value as EmailLanguage) : "en";
}
function resolveCampaignTone(value: string | undefined): EmailTone {
  return EMAIL_TONES.some(({ code }) => code === value) ? (value as EmailTone) : "warm-plain";
}
function formatCampaignDate(date: Date): string {
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}
function parseDateOrNull(value: string | null | undefined): Date | null {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session, admin } = await authenticate.admin(request);
  const url = new URL(request.url);

  // Catalog search for the picker UI — real store data, not the campaign list.
  const kind = url.searchParams.get("kind");
  if (kind === "products") {
    const products = await searchCampaignProducts(admin, url.searchParams.get("q") ?? "");
    return { products };
  }
  if (kind === "collections") {
    const collections = await searchCampaignCollections(admin, url.searchParams.get("q") ?? "");
    return { collections };
  }

  const search = url.searchParams.get("q")?.trim().slice(0, 100) ?? "";
  const requestedPage = Number(url.searchParams.get("page") ?? "1");
  const page = Number.isInteger(requestedPage) && requestedPage > 0 ? requestedPage : 1;

  const where = {
    shop: session.shop,
    ...(search ? { name: { contains: search } } : {}),
  };
  const total = await db.campaign.count({ where });
  // The unverified-domain cap counts every campaign, not the search result.
  const [shopCampaignCount, sendingDomain, postalLine] = await Promise.all([
    search ? db.campaign.count({ where: { shop: session.shop } }) : Promise.resolve(total),
    getSendingDomainSummary(session.shop),
    previewFooterLine(admin, session.shop),
  ]);
  const pageCount = Math.max(1, Math.ceil(total / CAMPAIGN_PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const rows = await db.campaign.findMany({
    where,
    orderBy: { createdAt: "desc" },
    skip: (safePage - 1) * CAMPAIGN_PAGE_SIZE,
    take: CAMPAIGN_PAGE_SIZE,
  });

  return {
    search,
    page: safePage,
    total,
    pageCount,
    sendingDomain,
    campaignLimit: {
      max: UNVERIFIED_CAMPAIGN_LIMIT,
      used: shopCampaignCount,
      reached: campaignLimitReached(shopCampaignCount, sendingDomain?.status),
    },
    campaigns: rows.map((row) => ({
      id: row.id,
      name: row.name,
      date: formatCampaignDate(row.updatedAt),
      emails: 1,
      status: capitalize(row.status),
      subject: row.subject ?? "",
      previewText: row.previewText ?? "",
      html: row.html ? withComplianceFooter(row.html, { postalLine, unsubscribeUrl: null }) : "",
    })),
  };
};

type GenerateCampaignRequest = {
  prompt: string;
  feature: Feature;
  productIds: string[];
  collectionId: string | null;
  discountMethod: DiscountMethod;
  discountCode: string | null;
  discountType: DiscountType;
  discountValue: string | null;
  startAt: string | null;
  endAt: string | null;
};

type NormalizedDiscount = {
  method: DiscountMethod;
  code: string | null;
  type: DiscountType;
  value: string | null;
  currency: string;
  startsAt: Date | null;
  endsAt: Date | null;
};

function normalizeDiscount(parsed: GenerateCampaignRequest): NormalizedDiscount {
  if (parsed.discountMethod !== "code") {
    return { method: "none", code: null, type: "percentage", value: null, currency: "USD", startsAt: null, endsAt: null };
  }
  const code = (parsed.discountCode ?? "").trim().slice(0, 40) || null;
  const value = (parsed.discountValue ?? "").trim().slice(0, 20) || null;
  const type: DiscountType = parsed.discountType === "fixed" ? "fixed" : "percentage";
  return {
    method: code && value ? "code" : "none",
    code,
    type,
    value,
    currency: "USD",
    startsAt: parseDateOrNull(parsed.startAt),
    endsAt: parseDateOrNull(parsed.endAt),
  };
}

// The brief is authoritative per NEWSLETTER_SKELETON_PROMPT — supplying the
// real code and dates verbatim here is what lets the model use them without
// inventing anything.
function withDiscountContext(prompt: string, discount: NormalizedDiscount): string {
  if (discount.method !== "code" || !discount.code || !discount.value) return prompt;
  const amountLabel = discount.type === "percentage" ? `${discount.value}%` : `${discount.value} ${discount.currency}`;
  const windowLabel =
    discount.startsAt && discount.endsAt
      ? ` Valid ${discount.startsAt.toISOString().slice(0, 10)} through ${discount.endsAt.toISOString().slice(0, 10)}.`
      : "";
  return `${prompt}\n\nReal discount to mention: code "${discount.code}" for ${amountLabel} off.${windowLabel} Use this exact code; never invent a different one.`;
}

function discountLabel(discount: NormalizedDiscount): string {
  if (discount.method !== "code" || !discount.code || !discount.value) return "No discount";
  const suffix = discount.type === "percentage" ? "%" : ` ${discount.currency}`;
  return `Discount ${discount.value}${suffix} · Code ${discount.code}`;
}

// A background-removed "cutout" of one product's real photo, offered to the
// generator alongside the original so it can pick whichever suits the
// composition (see newsletter-prompt.ts). Best-effort and entirely optional:
// unset REMOVE_BG_API_KEY and this always returns null with no extra cost or
// latency. ProductImageCutout caches a hit so the same product is never
// billed to the (paid, third-party) removal API more than once.
async function resolveProductCutout(
  admin: GraphqlAdmin,
  shop: string,
  productId: string,
  imageUrl: string,
): Promise<string | null> {
  if (!isBackgroundRemovalConfigured()) return null;
  const cached = await db.productImageCutout.findUnique({
    where: {
      shop_productId_sourceImageUrl: { shop, productId, sourceImageUrl: imageUrl },
    },
  });
  if (cached) return cached.cutoutImageUrl;

  const removed = await removeImageBackground(imageUrl);
  if (!removed) return null;
  const uploadedUrl = await uploadImageBufferToShopify(admin, {
    bytes: removed.bytes,
    contentType: removed.contentType,
    filename: `${productId.replace(/[^a-zA-Z0-9]/g, "-")}-cutout.png`,
    alt: "Product photo with background removed",
  });
  if (!uploadedUrl) return null;

  try {
    await db.productImageCutout.create({
      data: { shop, productId, sourceImageUrl: imageUrl, cutoutImageUrl: uploadedUrl },
    });
  } catch {
    // A concurrent request may have already cached this exact triple — the
    // upload above still succeeded, so use it regardless of the race.
  }
  return uploadedUrl;
}

// One planned photo, generated, reviewed, and hosted by the shared helper
// (dashboard/generated-photo.server.ts). Resolves to the hosted URL or null.
async function renderCampaignPhoto(
  admin: GraphqlAdmin,
  input: CampaignPlanInput,
  image: CampaignImageBrief,
  filename: string,
): Promise<string | null> {
  const result = await renderReviewedPhoto(admin, {
    brief: image,
    shopName: input.shopName,
    products: input.products,
    filename,
  });
  return result.url;
}

// The campaign's creative direction (see campaign-creative-plan.ts). Claude
// plans the whole email — which sections, how many, in what order, and
// whether any earns a generated photo — then the photos start rendering in
// the background. The designer gets the plan straight away with a pending
// placeholder per photo (generated-photo-slots.ts), so writing the email
// and rendering its photos overlap instead of running back to back.
// Best-effort end to end: unset OPENAI_API_KEY skips photos, and a planning
// error means the designer composes freely exactly as before.
async function planCreativeDirection(
  admin: GraphqlAdmin,
  input: CampaignPlanInput,
): Promise<{
  concept: string | null;
  sections: NewsletterSection[];
  generatedImages: NewsletterGeneratedImage[];
  photos: Promise<Map<string, string | null>>;
}> {
  let plan: Awaited<ReturnType<typeof planCampaignCreative>>;
  try {
    plan = await planCampaignCreative(input);
  } catch (error) {
    console.error("Campaign creative planning failed:", error);
    return { concept: null, sections: [], generatedImages: [], photos: Promise.resolve(new Map()) };
  }
  console.info(
    `Campaign creative plan: ${plan.sections.map((section) => section.type).join(" → ")}; ` +
      `${plan.images.length} photo(s). ${plan.reasoning} ` +
      `(planner tokens in/out ${plan.usage.inputTokens}/${plan.usage.outputTokens})`,
  );

  const briefs = isImageGenerationConfigured() ? plan.images : [];
  // Data checks only (real products, collections, a discount code); photo
  // failures are handled after rendering by removing that one <img>.
  const sections = finalizeSections(plan.sections, {
    availableImages: new Map(briefs.map((image) => [image.key, image])),
    hasCollections: input.collections.length > 0,
    hasDiscountCode: input.hasDiscountCode,
  });
  const placed = new Set(sections.map((section) => section.imageKey).filter(Boolean));
  const toRender = briefs.filter((image) => placed.has(image.key));

  const stamp = Date.now();
  const photos = Promise.all(
    toRender.map(async (image, index) => {
      const url = await renderCampaignPhoto(
        admin,
        input,
        image,
        `nomi-campaign-${stamp}-${index + 1}-${image.role}.jpg`,
      );
      return [image.key, url] as const;
    }),
  ).then((entries) => new Map(entries));

  return {
    concept: plan.concept || null,
    sections,
    generatedImages: toRender.map((image) => ({
      key: image.key,
      url: generatedPhotoPlaceholder(image.key),
      alt: image.alt,
      role: image.role,
      ...imageDimensions(image.aspect),
      productIds: image.productIds,
    })),
    photos,
  };
}

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session, admin } = await authenticate.admin(request);
  const formData = await request.formData();
  const payload = formData.get("payload");
  if (typeof payload !== "string") {
    return { error: "Missing request data." };
  }

  let parsed: GenerateCampaignRequest;
  try {
    parsed = JSON.parse(payload) as GenerateCampaignRequest;
  } catch {
    return { error: "Malformed request." };
  }

  if (EMAIL_GENERATION_PAUSED) {
    return { error: "Email generation is paused until you choose to start it." };
  }

  // Checked before any generation cost is spent.
  const [campaignCount, domain] = await Promise.all([
    db.campaign.count({ where: { shop: session.shop } }),
    getSendingDomainSummary(session.shop),
  ]);
  if (campaignLimitReached(campaignCount, domain?.status)) {
    return { error: CAMPAIGN_LIMIT_MESSAGE };
  }
  const allowance = await checkAllowance(session.shop, "campaign");
  if (!allowance.allowed) return { error: allowance.message ?? "Your plan's campaigns are used up." };

  const prompt = parsed.prompt.trim();
  if (!prompt || prompt.length > 1000) {
    return { error: "Describe the campaign in 1–1000 characters." };
  }

  const settings = await db.shopSettings.findUnique({
    where: { shop: session.shop },
    select: { language: true, tone: true },
  });
  const language = resolveCampaignLanguage(settings?.language);
  const tone = resolveCampaignTone(settings?.tone);

  let products: CampaignCatalogProduct[] = [];
  let featuredCollectionId: string | null = null;
  let featuredTitle: string | null = null;

  try {
    if (parsed.feature === "product") {
      products = await loadCampaignProductsByIds(admin, parsed.productIds.slice(0, 1));
      featuredTitle = products[0]?.title ?? null;
    } else if (parsed.feature === "all_products") {
      products = await loadCampaignProductsByIds(admin, parsed.productIds.slice(0, 3));
      featuredTitle = products.map((product) => product.title).join(", ") || null;
    } else if (parsed.feature === "collection" && parsed.collectionId) {
      const collection = await loadCampaignCollectionProducts(admin, parsed.collectionId);
      products = collection?.products ?? [];
      featuredCollectionId = parsed.collectionId;
      featuredTitle = collection?.title ?? null;
    }
  } catch (error) {
    console.error("Campaign catalog lookup failed:", error);
    return { error: "Couldn't load the selected products — try again." };
  }

  // An approved Brand Studio identity makes the campaign wear the merchant's
  // real brand (name, palette, voice, image treatment) instead of an
  // invented skin, and tells the photo planner what the store is about.
  // The brand name comes from Brand Studio's evidence (the merchant's real
  // name), never brandSystem.name, which names the creative direction.
  const [storeName, approvedBrand, brandProfile] = await Promise.all([
    loadDashboardShopName(admin),
    loadApprovedBrandIdentity(session.shop, null).catch(() => null),
    db.brandStudioProfile.findUnique({ where: { shop: session.shop } }).catch(() => null),
  ]);
  const brandIdentity = approvedBrand ?? undefined;
  const approvedFamily = brandIdentity && brandProfile ? getApprovedBrandStudioFamily(brandProfile) : null;
  const shopName = approvedFamily?.evidence.shopName?.trim() || storeName;
  const discount = normalizeDiscount(parsed);
  const enrichedPrompt = withDiscountContext(prompt, discount);

  // Best-effort: a failed or unconfigured cutout never blocks generation —
  // resolveProductCutout always falls back to null, and the prompt is told
  // to use the real photo whenever no cutout is present.
  // The cutout cache and remove.bg are keyed on the original photo URL, so
  // email-sized URLs are only swapped in after the cutout is resolved.
  const startedAt = Date.now();
  const storeLinksPromise = loadCampaignStoreLinks(admin);
  const productsWithCutouts = await Promise.all(
    products.map(async (product) => {
      const cutoutImageUrl = product.imageUrl
        ? await resolveProductCutout(admin, session.shop, product.id, product.imageUrl)
        : null;
      const [imageUrl, emailCutoutUrl] = await Promise.all([
        optimizeEmailImageUrl(product.imageUrl),
        optimizeEmailImageUrl(cutoutImageUrl, { transparent: true }),
      ]);
      return { ...product, imageUrl, cutoutImageUrl: emailCutoutUrl };
    }),
  );

  const newsletterProducts: NewsletterProduct[] = productsWithCutouts.map(
    ({ id, title, price, imageUrl, productUrl, cutoutImageUrl, productType, description }) => ({
      id,
      title,
      price,
      imageUrl,
      productUrl,
      cutoutImageUrl,
      productType: productType ?? null,
      description: description ?? null,
    }),
  );
  const storeLinks = await storeLinksPromise;
  // Every campaign carries a call to action, so a destination must always
  // exist: the shop's .myshopify.com address always serves its storefront
  // when the primary-domain lookup fails.
  const storefrontUrl = storeLinks.storefrontUrl ?? `https://${session.shop}`;
  const creative = await planCreativeDirection(admin, {
    shopName,
    prompt: enrichedPrompt,
    products: newsletterProducts,
    collections: storeLinks.collections,
    storefrontUrl,
    hasDiscountCode: discount.method === "code" && Boolean(discount.code),
    brandIdentity,
  });
  const plannedAt = Date.now();

  let html: string;
  try {
    html = await generateNewsletterEmail({
      shopName,
      language,
      tone,
      prompt: enrichedPrompt,
      products: newsletterProducts,
      generatedImages: creative.generatedImages,
      concept: creative.concept,
      sections: creative.sections,
      collections: storeLinks.collections,
      storefrontUrl,
      brandIdentity,
    });
  } catch (error) {
    console.error("Campaign generation failed:", error);
    return { error: error instanceof Error ? error.message : "Couldn't generate that campaign — try again." };
  }
  const writtenAt = Date.now();
  const photos = resolveGeneratedPhotoPlaceholders(html, await creative.photos);
  html = photos.html;
  console.info(
    `Campaign timing: planning ${Math.round((plannedAt - startedAt) / 1000)}s, ` +
      `email ${Math.round((writtenAt - plannedAt) / 1000)}s, ` +
      `waiting on photos ${Math.round((Date.now() - writtenAt) / 1000)}s; ` +
      `photos placed [${photos.placed.join(", ")}], removed [${photos.removed.join(", ")}]`,
  );

  const name = capitalize(prompt);
  const subject =
    discount.method === "code" && discount.value
      ? `${discount.value}${discount.type === "percentage" ? "%" : ` ${discount.currency}`} Off — ${name}`
      : name;
  const previewText = featuredTitle ? `Featuring ${featuredTitle}.` : "A new campaign from your shop.";

  const campaign = await db.campaign.create({
    data: {
      shop: session.shop,
      status: "draft",
      method: "ai",
      name,
      prompt,
      feature: parsed.feature,
      featuredProductIds: JSON.stringify(products.map((product) => product.id)),
      featuredCollectionId,
      discountMethod: discount.method,
      discountCode: discount.code,
      discountType: discount.type,
      discountValue: discount.value,
      discountStartsAt: discount.startsAt,
      discountEndsAt: discount.endsAt,
      subject,
      previewText,
      html,
    },
  });
  await recordUsage(session.shop, "campaign");

  return {
    campaign: {
      id: campaign.id,
      name: campaign.name,
      subject,
      previewText,
      discountLine: discountLabel(discount),
      html: withComplianceFooter(html, { postalLine: await previewFooterLine(admin, session.shop), unsubscribeUrl: null }),
    },
  };
};

// --- Create Campaign flow -------------------------------------------------
// A picker-driven creation experience: describe the campaign, search the real
// catalogue for what to feature, set a discount, then generate a real
// campaign draft with Claude.

type Feature = "product" | "collection" | "all_products";
type DiscountMethod = "code" | "none";
type DiscountType = "percentage" | "fixed";
type ModalStage = "closed" | "configure" | "generating";

// Mirrors the real pipeline (plan, then the email and its photos in
// parallel, then photo review and placement), paced by AI_LIVE_STEP_MS to
// the ~1–2 minutes a campaign actually takes.
const AI_ROWS = [
  "Reading your brief and products",
  "Planning the email's sections",
  "Designing the email and creating photos",
  "Checking every photo against your products",
  "Placing photos in your email",
  "Finalizing your email campaign",
];
const AI_LIVE_STEP_MS = 18_000;
const SETTLE_MS = 1500;

function randomDiscountCode() {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  let out = "";
  for (let i = 0; i < 10; i += 1) out += chars[Math.floor(Math.random() * chars.length)];
  return out;
}
function capitalize(value: string) {
  return value.replace(/\b\w/g, (c) => c.toUpperCase());
}
function isoDateOffset(days: number) {
  const date = new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
}


// The just-created campaign, shown as a card until the merchant views the list.
type Reveal = { id: string; title: string; subject: string; preview: string; discountLine: string; html: string };

function CreateCampaignModal({ stage, onClose, onGenerate, generatingStep,
  prompt, onPromptChange, feature, onFeatureProduct, onFeatureCollection,
  onFeatureAllProducts, selectedProduct, onSelectedProductChange, selectedCollection, onSelectedCollectionChange,
  selectedProducts, onSelectedProductsChange,
  discountMethod, onDiscountCode, onDiscountNone, discountCode,
  onDiscountCodeChange, onGenerateRandomCode, discountType, onDiscountTypeChange, discountValue,
  onDiscountValueChange, discountSuffix, startDate, onStartDateChange, startTime, onStartTimeChange,
  endDate, onEndDateChange, endTime, onEndTimeChange, generateError }: {
  stage: Extract<ModalStage, "configure" | "generating">;
  onClose: () => void;
  onGenerate: () => void;
  generatingStep: number;
  prompt: string;
  onPromptChange: (value: string) => void;
  feature: Feature;
  onFeatureProduct: () => void;
  onFeatureCollection: () => void;
  onFeatureAllProducts: () => void;
  selectedProduct: CampaignCatalogProduct | null;
  onSelectedProductChange: (product: CampaignCatalogProduct) => void;
  selectedCollection: CampaignCatalogCollection | null;
  onSelectedCollectionChange: (collection: CampaignCatalogCollection) => void;
  selectedProducts: CampaignCatalogProduct[];
  onSelectedProductsChange: (products: CampaignCatalogProduct[]) => void;
  discountMethod: DiscountMethod;
  onDiscountCode: () => void;
  onDiscountNone: () => void;
  discountCode: string;
  onDiscountCodeChange: (value: string) => void;
  onGenerateRandomCode: () => void;
  discountType: DiscountType;
  onDiscountTypeChange: (value: DiscountType) => void;
  discountValue: string;
  onDiscountValueChange: (value: string) => void;
  discountSuffix: string;
  startDate: string;
  onStartDateChange: (value: string) => void;
  startTime: string;
  onStartTimeChange: (value: string) => void;
  endDate: string;
  onEndDateChange: (value: string) => void;
  endTime: string;
  onEndTimeChange: (value: string) => void;
  generateError: string | null;
}) {
  useEffect(() => {
    if (stage !== "configure") return;
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [stage, onClose]);

  return (
    <div className="nomi-cc-backdrop" role="presentation">
      <div className="nomi-cc-modal" role="dialog" aria-modal="true" aria-label="Create Campaign">
        {stage === "configure" ? (
          <>
            <div className="nomi-cc-modal-head">
              <h2>Create Campaign</h2>
              <button type="button" className="nomi-cc-close" aria-label="Close" onClick={onClose}>
                <svg width="15" height="15" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5l14 14M19 5L5 19" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" /></svg>
              </button>
            </div>

            <div className="nomi-cc-body">
                <>
                  <div>
                    <span className="nomi-cc-label" style={{ color: "var(--nomi-cyan-700)", display: "inline-flex", alignItems: "center", gap: 5 }}>
                      Tell Nomi AI more about this campaign
                      <svg width="11" height="11" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l1.6 5.2L19 10l-5.4 1.8L12 17l-1.6-5.2L5 10l5.4-1.8Z" fill="#006786" /></svg>
                    </span>
                    <div className="nomi-cc-prompt-wrap">
                      <textarea className="nomi-cc-prompt" value={prompt} onChange={(e) => onPromptChange(e.target.value)} placeholder="e.g. flash sale, restock announcement, holiday gift guide" />
                      <div className="nomi-cc-prompt-tools">
                        <span title="Feature a product" className="nomi-cc-prompt-tool is-feature" style={PROMPT_TOOL_STYLE}>
                          <svg width="11" height="11" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7l8-4 8 4v10l-8 4-8-4Z" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinejoin="round" /></svg>
                        </span>
                      </div>
                    </div>
                    {generateError ? <p className="nomi-cc-generate-error" style={GENERATE_ERROR_STYLE}>{generateError}</p> : null}
                  </div>

                  <div>
                    <span className="nomi-cc-label">What should the campaign feature?</span>
                    <div className="nomi-cc-feature-row">
                      <button type="button" className={`nomi-cc-feature-btn${feature === "product" ? " is-active" : ""}`} onClick={onFeatureProduct}>Product</button>
                      <button type="button" className={`nomi-cc-feature-btn${feature === "collection" ? " is-active" : ""}`} onClick={onFeatureCollection}>Collection</button>
                      <button type="button" className={`nomi-cc-feature-btn${feature === "all_products" ? " is-active" : ""}`} onClick={onFeatureAllProducts}>All Products</button>
                    </div>
                    {feature === "collection" ? (
                      <>
                        <span className="nomi-cc-label" style={{ marginBottom: 6, fontWeight: 700, fontSize: 12 }}>Featured Collection</span>
                        <CollectionPicker value={selectedCollection} onChange={onSelectedCollectionChange} placeholder="Select a collection" />
                      </>
                    ) : feature === "product" ? (
                      <>
                        <span className="nomi-cc-label" style={{ marginBottom: 6, fontWeight: 700, fontSize: 12 }}>Featured Product</span>
                        <SingleProductPicker value={selectedProduct} onChange={onSelectedProductChange} placeholder="Select a product" />
                      </>
                    ) : (
                      <>
                        <span className="nomi-cc-label" style={{ marginBottom: 6, fontWeight: 700, fontSize: 12 }}>Showcase these products (up to 3)</span>
                        <MultiProductPicker value={selectedProducts} onChange={onSelectedProductsChange} max={3} />
                      </>
                    )}
                  </div>
                </>

              <div className="nomi-cc-discount-box">
                <span className="nomi-cc-discount-title">Campaign Discount</span>
                <span className="nomi-cc-label">Method</span>
                <div className="nomi-cc-feature-row">
                  <button type="button" className={`nomi-cc-feature-btn${discountMethod === "code" ? " is-active" : ""}`} onClick={onDiscountCode}>Discount Code</button>
                  <button type="button" className={`nomi-cc-feature-btn${discountMethod === "none" ? " is-active" : ""}`} onClick={onDiscountNone}>No Discount</button>
                </div>

                {discountMethod === "code" ? (
                  <>
                    <div className="nomi-cc-discount-row">
                      <span className="nomi-cc-fieldlabel">Discount Code</span>
                      <button type="button" className="nomi-cc-random-code" onClick={onGenerateRandomCode}>Generate random code</button>
                    </div>
                    <input key={discountCode} type="text" className="nomi-cc-input nomi-cc-code-input" value={discountCode} onChange={(e) => onDiscountCodeChange(e.target.value)} />

                    <span className="nomi-cc-label" style={{ fontWeight: 700, fontSize: 12 }}>Discount Value</span>
                    <div className="nomi-cc-value-row">
                      <select className="nomi-cc-select nomi-cc-value-select" value={discountType} onChange={(e) => onDiscountTypeChange(e.target.value as DiscountType)}>
                        <option value="percentage">Percentage</option>
                        <option value="fixed">Fixed amount</option>
                      </select>
                      <div className="nomi-cc-value-field">
                        <input type="number" className="nomi-cc-input nomi-cc-value-input" style={{ marginBottom: 0 }} value={discountValue} onChange={(e) => onDiscountValueChange(e.target.value)} />
                        <span className="nomi-cc-value-suffix">{discountSuffix}</span>
                      </div>
                    </div>

                    <span className="nomi-cc-label" style={{ fontWeight: 700, fontSize: 12 }}>Discount Active Dates</span>
                    <div className="nomi-cc-dates">
                      <div><small>Start date</small><input type="date" className="nomi-cc-date-input" value={startDate} onChange={(e) => onStartDateChange(e.target.value)} /></div>
                      <div><small>Start time</small><input type="time" className="nomi-cc-date-input" value={startTime} onChange={(e) => onStartTimeChange(e.target.value)} /></div>
                      <div><small>End date</small><input type="date" className="nomi-cc-date-input" value={endDate} onChange={(e) => onEndDateChange(e.target.value)} /></div>
                      <div><small>End time</small><input type="time" className="nomi-cc-date-input" value={endTime} onChange={(e) => onEndTimeChange(e.target.value)} /></div>
                    </div>
                  </>
                ) : null}
              </div>
            </div>

            <div className="nomi-cc-modal-foot">
              <button type="button" className="nomi-cc-discard" onClick={onClose}>Discard</button>
              <button type="button" className="nomi-cc-generate" onClick={onGenerate}>
                <svg width="12" height="12" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3l1.6 5.2L19 10l-5.4 1.8L12 17l-1.6-5.2L5 10l5.4-1.8Z" fill="currentColor" /></svg>
                Generate
              </button>
            </div>
          </>
        ) : (
          <GeneratingProgress title="Generating Your Campaign" rows={AI_ROWS} step={generatingStep} note="This usually takes 1–2 minutes." />
        )}
      </div>
    </div>
  );
}

