const DIALOG_KICKER_STYLE: React.CSSProperties = { display: "block", font: '600 11px/1 "IBM Plex Sans", sans-serif', letterSpacing: ".04em", textTransform: "uppercase", color: "#0088b0" };
const DIALOG_CLOSE_STYLE: React.CSSProperties = { width: 28, height: 28, display: "grid", placeItems: "center", border: 0, borderRadius: 6, background: "transparent", color: "#605d5d", cursor: "pointer", flexShrink: 0 };
