const DIALOG_SAVE_STYLE: React.CSSProperties = { height: 40, padding: "0 18px", borderRadius: 999, border: 0, background: "#201e1d", color: "#f3f2f2", font: '600 13px/1 "IBM Plex Sans", sans-serif', cursor: "pointer" };
const DIALOG_SAVE_DISABLED_STYLE: React.CSSProperties = { ...DIALOG_SAVE_STYLE, background: "#d7d3d3", color: "#918d8d", cursor: "not-allowed" };

// The campaign-scoped counterpart of app._index.tsx's SubjectPreviewDialog
// (lifecycle recipes) — same fields, same validation shape, but posts to
// app.campaigns.metadata.tsx and updates a Campaign row instead of a
// BrandStudioProfile's approved recipe family.
function CampaignSubjectPreviewDialog({
  campaignId,
  campaignName,
  subject: initialSubject,
  previewText: initialPreviewText,
  onClose,
  onSaved,
}: {
  campaignId: string;
  campaignName: string;
  subject: string;
  previewText: string;
  onClose: () => void;
  onSaved: (result: { subject: string; previewText: string }) => void;
}) {
  const fetcher = useFetcher<CampaignMetadataActionResult>();
  const [subject, setSubject] = useState(initialSubject);
  const [previewText, setPreviewText] = useState(initialPreviewText);
  const subjectRef = useRef<HTMLInputElement>(null);
  const isSaving = fetcher.state !== "idle";
  const hasChanges = subject.trim() !== initialSubject.trim() || previewText.trim() !== initialPreviewText.trim();
  const isValid =
    subject.trim().length >= 3 && subject.trim().length <= 64 &&
    previewText.trim().length >= 3 && previewText.trim().length <= 140;

  useEffect(() => {
    subjectRef.current?.focus();
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape" && !isSaving) onClose(); };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [isSaving, onClose]);

  useEffect(() => {
    if (fetcher.state === "idle" && fetcher.data?.ok) {
      onSaved({ subject: fetcher.data.subject, previewText: fetcher.data.previewText });
      onClose();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetcher.state, fetcher.data]);

  return (
    <div style={DIALOG_BACKDROP_STYLE} role="presentation" onMouseDown={(e) => { if (e.target === e.currentTarget && !isSaving) onClose(); }}>
      <section style={DIALOG_STYLE} role="dialog" aria-modal="true" aria-label={`Edit subject and preview text for ${campaignName}`}>
        <div style={DIALOG_HEAD_STYLE}>
          <div>
            <span style={DIALOG_KICKER_STYLE}>Inbox details</span>
            <h3 style={DIALOG_TITLE_STYLE}>Edit subject &amp; preview</h3>
          </div>
          <button type="button" style={DIALOG_CLOSE_STYLE} onClick={onClose} disabled={isSaving} aria-label="Close">&times;</button>
        </div>
        <fetcher.Form method="post" action="/app/campaigns/metadata">
          <input type="hidden" name="campaignId" value={campaignId} />
          <div style={DIALOG_BODY_STYLE}>
            <label>
              <div style={DIALOG_LABEL_ROW_STYLE}>
                <span style={DIALOG_LABEL_STYLE}>Subject line</span>
                <span style={subject.length > 64 ? DIALOG_COUNT_OVER_STYLE : DIALOG_COUNT_STYLE}>{subject.length} / 64</span>
              </div>
              <input
                ref={subjectRef}
                type="text"
                name="subject"
                required
                minLength={3}
                maxLength={64}
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                style={DIALOG_INPUT_STYLE}
                autoComplete="off"
              />
            </label>
            <label>
              <div style={DIALOG_LABEL_ROW_STYLE}>
                <span style={DIALOG_LABEL_STYLE}>Preview text</span>
                <span style={previewText.length > 140 ? DIALOG_COUNT_OVER_STYLE : DIALOG_COUNT_STYLE}>{previewText.length} / 140</span>
              </div>
              <textarea
                name="previewText"
                required
                minLength={3}
                maxLength={140}
                rows={3}
                value={previewText}
                onChange={(e) => setPreviewText(e.target.value)}
                style={DIALOG_TEXTAREA_STYLE}
              />
            </label>
            {fetcher.data && !fetcher.data.ok ? <p style={DIALOG_ERROR_STYLE} role="alert">{fetcher.data.error}</p> : null}
          </div>
          <div style={DIALOG_FOOT_STYLE}>
            <button type="button" style={DIALOG_CANCEL_STYLE} onClick={onClose} disabled={isSaving}>Cancel</button>
            <button type="submit" style={!hasChanges || !isValid || isSaving ? DIALOG_SAVE_DISABLED_STYLE : DIALOG_SAVE_STYLE} disabled={isSaving || !hasChanges || !isValid}>
              {isSaving ? "Saving…" : "Save changes"}
            </button>
          </div>
        </fetcher.Form>
      </section>
    </div>
  );
}

// A verified domain becomes the From address (email-delivery/from-header.ts)
// and lifts the unverified campaign cap (SENDING_DOMAIN.md). Styled to match the merchant-approved reference
// banner (light-blue header strip, white body, outlined button). Every
// size is inline — see CAMPAIGNS.md on classes in the embedded iframe.
const DOMAIN_BANNER_DISMISS_KEY = "nomi:sending-domain-banner-dismissed";
const BANNER_FONT = 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';

// Once verified, the banner shrinks to one quiet line so the merchant can
// still see which address sends and replay the three setup pages.
function SendingDomainVerifiedRow({ domain }: { domain: string }) {
  return (
    <section
      aria-label="Sending domain"
      style={{ margin: "16px 0", display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", padding: "6px 8px 6px 16px", background: "#fff", border: "1px solid #e3dfdb", borderRadius: 2, fontFamily: BANNER_FONT, color: "#201e1d" }}
    >
      <p style={{ margin: 0, display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap", minWidth: 0, fontSize: 14, lineHeight: 1.45 }}>
        <span aria-hidden="true" style={{ width: 20, height: 20, flex: "none", display: "grid", placeItems: "center", borderRadius: "50%", background: "#0088b0", color: "#fff" }}>
          <svg width="11" height="11" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M4.5 10.5 L8.5 14.5 L15.5 6" /></svg>
        </span>
        <span>Sending from <strong style={{ fontWeight: 600, wordBreak: "break-all" }}>hello@{domain}</strong></span>
        <span style={{ padding: "2px 8px", background: "#e6f4f8", color: "#006b8b", fontSize: 11, fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase" }}>Verified</span>
      </p>
      <Link
        to="/app/sending-domain?replay=1"
        style={{ minHeight: 44, display: "inline-flex", alignItems: "center", gap: 6, padding: "0 12px", color: "#0088b0", fontSize: 14, fontWeight: 600, textDecoration: "none", whiteSpace: "nowrap" }}
      >
        <svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3.5 10 A6.5 6.5 0 1 0 5.4 5.4" /><path d="M3.5 3.5 V7 H7" /></svg>
        Replay setup
      </Link>
    </section>
  );
}

function SendingDomainNotice({ sendingDomain }: { sendingDomain: { domain: string; status: string; verified: boolean } | null }) {
  const [dismissed, setDismissed] = useState(false);
  useEffect(() => {
    try { setDismissed(window.sessionStorage.getItem(DOMAIN_BANNER_DISMISS_KEY) === "1"); } catch { /* storage blocked */ }
  }, []);
  if (sendingDomain?.verified) return <SendingDomainVerifiedRow domain={sendingDomain.domain} />;
  if (dismissed) return null;

  const dismiss = () => {
    setDismissed(true);
    try { window.sessionStorage.setItem(DOMAIN_BANNER_DISMISS_KEY, "1"); } catch { /* storage blocked */ }
  };

  const copy = !sendingDomain
    ? { title: "Send from your own domain", body: `Verify your domain so your emails come from hello@yourstore.com instead of Nomi’s address. Without one you can create ${UNVERIFIED_CAMPAIGN_LIMIT} campaigns.`, cta: "Setup Domain" }
    : sendingDomain.status === "temporary_failure"
      ? { title: `A DNS record for ${sendingDomain.domain} went missing`, body: "Emails send from Nomi’s address until every record is back at your domain provider.", cta: "Fix Records" }
      : sendingDomain.status === "failed"
        ? { title: `Verification stopped for ${sendingDomain.domain}`, body: "The DNS records weren’t found after 72 hours. Add them, then restart verification.", cta: "Restart Setup" }
        : { title: `Finish verifying ${sendingDomain.domain}`, body: "Add the DNS records at your domain provider, then verify them in Nomi. Until then emails send from Nomi’s address.", cta: "Continue Setup" };

  return (
    <section
      aria-label="Sending domain status"
      style={{ margin: "16px 0", background: "#fff", borderRadius: 12, overflow: "hidden", boxShadow: "0 1px 0 rgba(26,26,26,.07), 0 1px 3px rgba(26,26,26,.18)", fontFamily: BANNER_FONT, color: "#303030" }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 8, minHeight: 44, padding: "0 4px 0 16px", background: "#a4d0f8" }}>
        <svg width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="#1a1a1a" strokeWidth="1.6" strokeLinecap="round" aria-hidden="true" style={{ flex: "none" }}>
          <circle cx="10" cy="10" r="7.25" /><path d="M10 9.2 V13.6" /><path d="M10 6.4 V6.5" strokeWidth="2" />
        </svg>
        <strong style={{ flex: 1, minWidth: 0, fontSize: 14, fontWeight: 650, lineHeight: 1.4, color: "#1a1a1a", padding: "10px 0" }}>{copy.title}</strong>
        <button
          type="button"
          onClick={dismiss}
          aria-label="Dismiss"
          style={{ width: 44, height: 44, flex: "none", display: "grid", placeItems: "center", padding: 0, margin: 0, border: 0, borderRadius: 8, background: "transparent", color: "#1a1a1a", cursor: "pointer" }}
        >
          <svg width="16" height="16" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true"><path d="M5 5 L15 15 M15 5 L5 15" /></svg>
        </button>
      </div>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 16, flexWrap: "wrap", padding: "8px 16px" }}>
        <p style={{ margin: 0, flex: "1 1 280px", minWidth: 0, fontSize: 14, lineHeight: 1.45, color: "#303030" }}>{copy.body}</p>
        <Link
          to="/app/sending-domain"
          style={{ minHeight: 44, display: "inline-flex", alignItems: "center", flex: "none", textDecoration: "none" }}
        >
          <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", minHeight: 32, padding: "0 14px", background: "#fff", color: "#303030", border: 0, borderRadius: 8, boxShadow: "inset 0 -1px 0 #b5b5b5, 0 0 0 1px #d4d4d4", fontSize: 13, fontWeight: 650, whiteSpace: "nowrap", fontFamily: BANNER_FONT }}>{copy.cta}</span>
        </Link>
      </div>
    </section>
  );
}

export default function CampaignsPage() {
  // The route's loader also serves the picker's catalog-search JSON (the
  // `kind=products|collections` branches), so `typeof loader`'s inferred
  // return type is a union. Page navigation only ever hits the list branch
  // below, so this narrows to the shape this component actually renders.
  const { search, page, total, pageCount, campaigns, sendingDomain, campaignLimit } = useLoaderData() as {
    search: string;
    page: number;
    total: number;
    pageCount: number;
    sendingDomain: { domain: string; status: string; verified: boolean } | null;
    campaignLimit: { max: number; used: number; reached: boolean };
    campaigns: Array<{
      id: string;
      name: string;
      date: string;
      emails: number;
      status: string;
      subject: string;
      previewText: string;
      html: string;
    }>;
  };
  const pageHref = (target: number) => {
    const params = new URLSearchParams();
    if (search) params.set("q", search);
    params.set("page", String(target));
    return `?${params.toString()}`;
  };

  const generateFetcher = useFetcher<typeof action>();

  const [stage, setStage] = useState<ModalStage>("closed");
  const [prompt, setPrompt] = useState("");
  const [feature, setFeature] = useState<Feature>("product");
  const [selectedProduct, setSelectedProduct] = useState<CampaignCatalogProduct | null>(null);
  const [selectedCollection, setSelectedCollection] = useState<CampaignCatalogCollection | null>(null);
  const [selectedProducts, setSelectedProducts] = useState<CampaignCatalogProduct[]>([]);
  const [discountMethod, setDiscountMethod] = useState<DiscountMethod>("code");
  const [discountCode, setDiscountCode] = useState(() => randomDiscountCode());
  const [discountType, setDiscountType] = useState<DiscountType>("percentage");
  const [discountValue, setDiscountValue] = useState("25");
  const [startDate, setStartDate] = useState(() => isoDateOffset(0));
  const [startTime, setStartTime] = useState("09:00");
  const [endDate, setEndDate] = useState(() => isoDateOffset(3));
  const [endTime, setEndTime] = useState("23:59");
  const [generatingStep, setGeneratingStep] = useState(0);
  const [generateError, setGenerateError] = useState<string | null>(null);
  const [reveal, setReveal] = useState<Reveal | null>(null);
  const [revealKey, setRevealKey] = useState(0);
  const [previewCampaign, setPreviewCampaign] = useState<{ id: string; name: string; subject: string; previewText: string; html: string } | null>(null);
  const timersRef = useRef<number[]>([]);

  const clearTimers = () => {
    timersRef.current.forEach((id) => window.clearTimeout(id));
    timersRef.current = [];
  };
  useEffect(() => clearTimers, []);

  const openCreate = () => {
    if (campaignLimit.reached) return;
    clearTimers(); setGenerateError(null); setStage("configure");
  };
  const closeModal = () => { clearTimers(); setStage("closed"); };

  // The dashboard's "Create your first campaign" links here with ?create=1.
  // Open the modal once, then drop the param so a reload doesn't reopen it.
  const [searchParams, setSearchParams] = useSearchParams();
  const createRequested = searchParams.get("create") === "1";
  useEffect(() => {
    if (!createRequested) return;
    openCreate();
    setSearchParams((params) => { params.delete("create"); return params; }, { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [createRequested]);

  const discountSuffix = discountType === "percentage" ? "%" : "USD";

  const beginGenerating = () => {
    const trimmedPrompt = prompt.trim();
    if (!trimmedPrompt) { setGenerateError("Write what you want your campaign to be about."); return; }
    if (feature === "product" && !selectedProduct) { setGenerateError("Pick a product to feature."); return; }
    if (feature === "collection" && !selectedCollection) { setGenerateError("Pick a collection to feature."); return; }
    if (feature === "all_products" && selectedProducts.length === 0) { setGenerateError("Pick at least one product to feature."); return; }

    setGenerateError(null);
    clearTimers();
    setStage("generating");
    setGeneratingStep(0);

    const hasDates = discountMethod === "code" && startDate && endDate;
    const payload: GenerateCampaignRequest = {
      prompt: trimmedPrompt,
      feature,
      productIds:
        feature === "product" && selectedProduct ? [selectedProduct.id]
        : feature === "all_products" ? selectedProducts.map((product) => product.id)
        : [],
      collectionId: feature === "collection" ? selectedCollection?.id ?? null : null,
      discountMethod,
      discountCode: discountMethod === "code" ? discountCode : null,
      discountType,
      discountValue: discountMethod === "code" ? discountValue : null,
      startAt: hasDates ? `${startDate}T${startTime}` : null,
      endAt: hasDates ? `${endDate}T${endTime}` : null,
    };
    generateFetcher.submit({ payload: JSON.stringify(payload) }, { method: "post" });

    // Cycle through the phase labels while the real request is in flight,
    // capped one step short of the end so the animation never "finishes"
    // before the actual response arrives.
    const maxLiveStep = Math.max(0, AI_ROWS.length - 2);
    let step = 0;
    const interval = window.setInterval(() => {
      step = Math.min(step + 1, maxLiveStep);
      setGeneratingStep(step);
    }, AI_LIVE_STEP_MS);
    timersRef.current.push(interval as unknown as number);
  };

  // Finalizes the AI generate flow once the real server response lands.
  useEffect(() => {
    if (generateFetcher.state !== "idle" || !generateFetcher.data) return;
    const data = generateFetcher.data;
    if ("error" in data && data.error) {
      clearTimers();
      setGenerateError(data.error);
      setStage("configure");
      setGeneratingStep(0);
      return;
    }
    if ("campaign" in data && data.campaign) {
      const { campaign } = data;
      clearTimers();
      setGeneratingStep(AI_ROWS.length - 1);
      const timeout = window.setTimeout(() => {
        setStage("closed");
        setReveal({ id: campaign.id, title: campaign.name, subject: campaign.subject, preview: campaign.previewText, discountLine: campaign.discountLine, html: campaign.html });
        setRevealKey((key) => key + 1);
      }, SETTLE_MS);
      timersRef.current.push(timeout);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [generateFetcher.state, generateFetcher.data]);

  const showRedesignedEmpty = total === 0 && !reveal;
  const showReveal = Boolean(reveal);

  return (
    <main className="nomi-flow-page nomi-campaigns-page">
      <div className="nomi-flow-shell">
        <header className="nomi-flow-header">
          <div className="nomi-flow-title"><Link to="/app" className="nomi-flow-reference-arrow" aria-label="Back to home">←</Link><h1>Campaigns</h1></div>
          <div className="nomi-flow-header-actions" style={{ display: "flex", alignItems: "center", gap: 14, flexWrap: "wrap" }}>
            {!sendingDomain?.verified ? (
              <span id="campaign-limit-note" style={{ fontSize: 13, color: campaignLimit.reached ? "#a3004f" : "#605d5d" }}>
                {Math.min(campaignLimit.used, campaignLimit.max)} of {campaignLimit.max} campaigns used until your domain is verified
              </span>
            ) : null}
            <button
              type="button"
              className="nomi-flow-primary nomi-campaigns-create"
              onClick={openCreate}
              disabled={campaignLimit.reached}
              aria-describedby={!sendingDomain?.verified ? "campaign-limit-note" : undefined}
              title={campaignLimit.reached ? CAMPAIGN_LIMIT_MESSAGE : undefined}
              style={campaignLimit.reached ? { opacity: 0.45, cursor: "not-allowed" } : undefined}
            >
              <svg width="13" height="13" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true"><path d="M10 4 V16 M4 10 H16" /></svg>
              Create Campaign
            </button>
          </div>
        </header>

        <SendingDomainNotice sendingDomain={sendingDomain} />

        {showRedesignedEmpty ? (
          <div className="nomi-cc-empty">
            <div className="nomi-cc-empty-icon">
              <svg width="104" height="104" viewBox="0 0 120 120" aria-hidden="true">
                <circle cx="60" cy="60" r="50" fill="none" stroke="#e2ded8" strokeWidth="1.5" strokeDasharray="4 6" />
                <g transform="translate(35,25)">
                  <path d="M0 6a6 6 0 0 1 6-6h28l14 14v51a6 6 0 0 1-6 6H6a6 6 0 0 1-6-6Z" fill="#fff" stroke="#201e1d" strokeWidth="2" />
                  <path d="M34 0v14h14" fill="none" stroke="#201e1d" strokeWidth="2" strokeLinejoin="round" />
                  <rect x="9" y="13" width="11" height="11" rx="2" fill="#0088b0" />
                  <line x1="9" y1="32" x2="39" y2="32" stroke="#e2ded8" strokeWidth="3" strokeLinecap="round" />
                  <line x1="9" y1="41" x2="39" y2="41" stroke="#e2ded8" strokeWidth="3" strokeLinecap="round" />
                  <line x1="9" y1="50" x2="30" y2="50" stroke="#e2ded8" strokeWidth="3" strokeLinecap="round" />
                </g>
              </svg>
            </div>
            <div>
              <h2>No campaigns yet</h2>
              <p>Your campaigns will show up here once you create one.</p>
            </div>
            <button type="button" className="nomi-cc-empty-cta" onClick={openCreate} disabled={campaignLimit.reached}>Create Campaign</button>
          </div>
        ) : showReveal && reveal ? (
          <div className="nomi-cc-reveal" key={revealKey}>
            <p className="nomi-cc-reveal-count">1 campaign created</p>
            <div
              className="nomi-cc-reveal-card"
              role="button"
              tabIndex={0}
              aria-label={`Preview ${reveal.title}`}
              onClick={() => setPreviewCampaign({ id: reveal.id, name: reveal.title, subject: reveal.subject, previewText: reveal.preview, html: reveal.html })}
              onKeyDown={(event) => {
                if (event.key !== "Enter" && event.key !== " ") return;
                event.preventDefault();
                setPreviewCampaign({ id: reveal.id, name: reveal.title, subject: reveal.subject, previewText: reveal.preview, html: reveal.html });
              }}
            >
              <div className="nomi-cc-reveal-banner">
                <span className="nomi-cc-reveal-blob is-a" style={{ background: "#0088b0" }} />
                <span className="nomi-cc-reveal-blob is-b" style={{ background: "#d6006c" }} />
                <span className="nomi-cc-reveal-badge">{reveal.html ? "Click to preview" : "AI banner"}</span>
              </div>
              <div className="nomi-cc-reveal-body">
                <span className="nomi-cc-reveal-status">Draft</span>
                <h3 className="nomi-cc-reveal-title">{reveal.title}</h3>
                <p className="nomi-cc-reveal-subject"><b>Subject:</b> {reveal.subject}</p>
                <p className="nomi-cc-reveal-preview">{reveal.preview}</p>
                <div className="nomi-cc-reveal-foot">
                  <span>Created just now</span>
                  <span>{reveal.discountLine}</span>
                </div>
              </div>
            </div>
            <button type="button" className="nomi-cc-empty-cta" style={{ marginTop: 16 }} onClick={() => setReveal(null)}>View all campaigns</button>
          </div>
        ) : (
          <>

            <section className="nomi-campaigns-card" aria-label="Campaign list">
              <div className="nomi-campaigns-card-head">
                <span>{total} campaign{total === 1 ? "" : "s"}</span>
                <Form method="get" className="nomi-campaigns-search" role="search"><label htmlFor="campaign-search" className="nomi-visually-hidden">Search campaigns</label><input id="campaign-search" name="q" type="search" defaultValue={search} placeholder="Search campaigns" /><button type="submit" className="nomi-campaigns-icon-btn" aria-label="Search campaigns"><svg width="14" height="14" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.7" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5" /><path d="M13 13 L17 17" strokeLinecap="round" /></svg></button></Form>
              </div>

              <div className="nomi-table-responsive-wrap">
                <table className="nomi-campaigns-table"><colgroup><col style={{ width: "28%" }} /><col style={{ width: "14%" }} /><col style={{ width: "12%" }} /><col style={{ width: "12%" }} /><col style={{ width: "12%" }} /><col style={{ width: "12%" }} /><col style={{ width: "10%" }} /></colgroup><thead><tr><th>Campaign name</th><th>Updated</th><th>Emails</th><th>Open rate</th><th>Click rate</th><th>Revenue</th><th>Status</th></tr></thead>
                  <tbody>{campaigns.length ? campaigns.map((campaign) => <tr key={campaign.id}><td><button type="button" className="nomi-campaigns-name" onClick={() => setPreviewCampaign({ id: campaign.id, name: campaign.name, subject: campaign.subject, previewText: campaign.previewText, html: campaign.html })}>{campaign.name}</button></td><td className="nomi-campaigns-muted">{campaign.date}</td><td>{campaign.emails}</td><td>—</td><td>—</td><td>—</td><td><span className="nomi-campaigns-status">{campaign.status}</span></td></tr>) : <tr><td colSpan={7} className="nomi-campaigns-empty">{search ? `No campaigns match “${search}”.` : <><strong>No campaigns yet.</strong><span>Create a reviewed draft to see it here.</span></>}</td></tr>}</tbody>
                </table>
              </div>

              <div className="nomi-campaigns-pagination"><span>Page {page} of {pageCount}</span>{page > 1 ? <Link to={pageHref(page - 1)} className="nomi-campaigns-page-btn" aria-label="Previous page">‹</Link> : <button type="button" className="nomi-campaigns-page-btn" aria-label="Previous page" disabled>‹</button>}{page < pageCount ? <Link to={pageHref(page + 1)} className="nomi-campaigns-page-btn" aria-label="Next page">›</Link> : <button type="button" className="nomi-campaigns-page-btn" aria-label="Next page" disabled>›</button>}</div>
            </section>
          </>
        )}
      </div>

      {stage !== "closed" ? (
        <CreateCampaignModal
          stage={stage}
          onClose={closeModal}
          onGenerate={beginGenerating}
          generatingStep={generatingStep}
          prompt={prompt}
          onPromptChange={setPrompt}
          feature={feature}
          onFeatureProduct={() => setFeature("product")}
          onFeatureCollection={() => setFeature("collection")}
          onFeatureAllProducts={() => setFeature("all_products")}
          selectedProduct={selectedProduct}
          onSelectedProductChange={setSelectedProduct}
          selectedCollection={selectedCollection}
          onSelectedCollectionChange={setSelectedCollection}
          selectedProducts={selectedProducts}
          onSelectedProductsChange={setSelectedProducts}
          discountMethod={discountMethod}
          onDiscountCode={() => setDiscountMethod("code")}
          onDiscountNone={() => setDiscountMethod("none")}
          discountCode={discountCode}
          onDiscountCodeChange={setDiscountCode}
          onGenerateRandomCode={() => setDiscountCode(randomDiscountCode())}
          discountType={discountType}
          onDiscountTypeChange={setDiscountType}
          discountValue={discountValue}
          onDiscountValueChange={setDiscountValue}
          discountSuffix={discountSuffix}
          startDate={startDate}
          onStartDateChange={setStartDate}
          startTime={startTime}
          onStartTimeChange={setStartTime}
          endDate={endDate}
          onEndDateChange={setEndDate}
          endTime={endTime}
          onEndTimeChange={setEndTime}
          generateError={generateError}
        />
      ) : null}

      {previewCampaign ? (
        <CampaignPreviewModal campaign={previewCampaign} onClose={() => setPreviewCampaign(null)} />
      ) : null}
    </main>
  );
}

export const headers: HeadersFunction = (headersArgs) => boundary.headers(headersArgs);
